using System.Text;
using HakutaiKagami.Core.Messaging;
namespace HakutaiKagami.Core.Contracts;
public enum SurveyAction { Statement,Measurement,ReadBook,PostRate }
public enum LandTaxRate { Gentle=20,Ordinary=30,Heavy=40 }
public sealed record SurveyInput(EntityId Id,SurveyAction Action,EntityId Owner,EntityId Site,EntityId? Reference=null,LandTaxRate Rate=LandTaxRate.Ordinary);
public sealed record SurveyBook(EntityId Job,long At,long Revision,long Basis,bool Measured,string Description);
public sealed record SurveyEntry(SurveyInput Input,EntityId Actor,EntityId Principal,long At,long Revision,long Due,long Rice,long Coins,int Crew,SurveyBook? Result);
public sealed record SurveyPaper(string Id,EntityId Reading,EntityId Sender,EntityId Recipient,EntityId Address,EntityId Site,long At,long Revision,SurveyBook Book);
public sealed record SurveyState(int Schema,string Policy,SurveyEntry[] Entries,SurveyBook[] Books,SurveyPaper[] Papers);
public static class LandSurvey
{
 public const string Policy="local-statement-measurement-known-book-prospective-tax-decree-v1",MessageKind="land-survey-report";
 internal static SurveyEntry[] Entries(ContractWorld w)=>w.Surveys?.Entries??[];
 static void Need([System.Diagnostics.CodeAnalysis.DoesNotReturnIf(false)]bool c,string why){if(!c)throw new InvalidDataException(why);}
 static bool Before(SurveyEntry e,long at,long rev)=>e.At<at||e.At==at&&e.Revision<rev;
 static EntityId Id(string key)=>new("survey:"+ContractJson.Hash(Encoding.UTF8.GetBytes(key))[..28]);
 static bool Job(SurveyEntry e)=>e.Input.Action is SurveyAction.Statement or SurveyAction.Measurement;
 public static bool OwnIdUsed(ContractWorld w,EntityId id)=>Entries(w).Any(e=>e.Input.Id==id);
 static SurveyEntry Source(ContractWorld w,EntityId id)=>Entries(w).Single(e=>e.Input.Id==id);
 static bool Authority(ContractWorld w,EntityId actor,EntityId owner,EntityId site,long at,long rev)=>RegionalDomains.Owner(w,site)==owner&&RegionalDomains.Authority(w,actor,site,at,rev)&&TransportWork.At(w,actor,site,at,rev,true);
 static long TrueBasis(ContractWorld w,EntityId site,long at,long rev){using var _ccRev=ControlContext.At(rev);var a=CommunityEconomy.AccountAt(w,site,at,rev);return checked(CommunityEconomy.BaseHarvest*a.Water/100*(100+5*PublicWorks.Level(w,site,WorksKind.Agriculture,at,rev))/100);}
 static SurveyBook Complete(ContractWorld w,SurveyEntry e,long rev){using var _ccRev=ControlContext.At(rev);long basis=TrueBasis(w,e.Input.Site,e.Due,rev);bool measured=e.Input.Action==SurveyAction.Measurement;if(!measured){var h=ContractJson.Hash(Encoding.UTF8.GetBytes(w.Seed+"/statement/"+e.Input.Site.Value+"/"+e.Due/86400));int percent=90+Convert.ToInt32(h[..2],16)%21;basis=checked(basis*percent/100);}return new(e.Input.Id,e.Due,rev,basis,measured,measured?"試作の基準収穫を実測した検地簿。史実の石高や実地図の測量値ではない":"村代表が見積もった指出。確定した実測値や不正の証拠ではない");}
 public static SurveyBook[] KnownBooks(ContractWorld w,EntityId actor,long at=long.MaxValue,long rev=long.MaxValue){using var _ccRev=ControlContext.At(rev);var rows=Entries(w).Where(e=>e.Input.Action==SurveyAction.ReadBook&&e.Actor==actor&&Before(e,at,rev)).Select(e=>e.Result!);var papers=(w.Surveys?.Papers??[]).Where(p=>p.Recipient==actor&&p.At<=at&&p.Revision<rev&&MessageFlow.LearnedAt(w.Messaging,p.Id,actor.Value) is {} learned&&learned<=at).Select(p=>p.Book);return rows.Concat(papers).DistinctBy(b=>b.Job).ToArray();}
 public static SurveyEntry[] Planned(ContractWorld w,EntityId actor)=>Entries(w).Where(e=>Job(e)&&(e.Actor==actor||Authority(w,actor,e.Input.Owner,e.Input.Site,w.ElapsedSeconds,w.CommitSequence+1))).ToArray();
 public static SurveyPaper[] Inbox(ContractWorld w,EntityId actor)=>(w.Surveys?.Papers??[]).Where(p=>p.Recipient==actor&&w.Messaging.Attempts.Any(a=>a.MessageId==p.Id&&a.ReceiverId==actor.Value&&a.Status==AttemptStatus.Delivered)).ToArray();
 public static string? Address(ContractWorld w,MessageEnvelope m)=>w.Surveys?.Papers.SingleOrDefault(p=>p.Id==m.Id) is {} p?NewGameWorld.Node(p.Address.Value):null;
 internal static long Assessment(ContractWorld w,EntityId site,long harvest,long at,long rev){using var _ccRev=ControlContext.At(rev);var decree=Entries(w).Where(e=>e.Input.Site==site&&e.Input.Action==SurveyAction.PostRate&&e.Due<=at&&Before(e,at,rev)).OrderBy(e=>e.Revision).LastOrDefault();if(decree==null)return checked(harvest*3/10);long basis=decree.Result==null?harvest:Math.Min(harvest,decree.Result.Basis);return checked(basis*(int)decree.Input.Rate/100);}
 public static SurveyEntry? EffectiveDecree(ContractWorld w,EntityId site,long at)=>Entries(w).Where(e=>e.Input.Site==site&&e.Input.Action==SurveyAction.PostRate&&e.Due<=at&&e.At<=at).OrderBy(e=>e.Revision).LastOrDefault();
 internal static int Pressure(ContractWorld w,EntityId site,long at){var decree=EffectiveDecree(w,site,at);return decree?.Input.Rate switch{LandTaxRate.Heavy=>15+(int)Math.Min(10,Math.Max(0,(at-decree.Due)/(30*86400))*2),LandTaxRate.Gentle=>-5,_=>0};}
 internal static int LaborAt(ContractWorld w,EntityId site,long at,long rev)=>Entries(w).Where(e=>Job(e)&&e.Input.Site==site&&Before(e,at,rev)&&at<e.Due).Sum(e=>e.Crew);
 internal static long LaborSeconds(ContractWorld w,EntityId site,long start,long end,long rev)=>Entries(w).Where(e=>Job(e)&&e.Input.Site==site&&e.Revision<rev).Sum(e=>Math.Max(0,Math.Min(end,e.Due)-Math.Max(start,e.At))*e.Crew);
 internal static long CashNet(ContractWorld w,EntityId site,long at,long rev)=>-Entries(w).Where(e=>e.Input.Site==site&&Before(e,at,rev)).Sum(e=>e.Coins);
 internal static long BudgetUsed(ContractWorld w,EntityId site,long at,long rev,EntityId? actor=null){using var _ccRev=ControlContext.At(rev);var date=DateOnly.Parse(w.EpochDate).AddDays((int)(at/86400));return Entries(w).Where(e=>e.Input.Site==site&&Before(e,at,rev)&&(actor==null||e.Actor==actor||CommunityStewardship.SharedDelegationBudget(w,site,at,rev)&&CommunityStewardship.DelegatedCharge(w,e.Actor,site,e.At,e.Revision))).Where(e=>{var d=DateOnly.Parse(w.EpochDate).AddDays((int)(e.At/86400));return d.Year==date.Year&&d.Month==date.Month;}).Sum(e=>e.Coins);}
 internal static (long At,long Revision,long Amount)[] RiceTransfers(ContractWorld w,EntityId site,long at,long rev)=>Entries(w).Where(e=>e.Input.Site==site&&e.Rice>0&&Before(e,at,rev)).Select(e=>(e.At,e.Revision,-e.Rice)).ToArray();
 static SurveyEntry Make(ContractWorld w,SurveyInput i,EntityId actor,long at,long rev){using var _ccRev=ControlContext.At(rev);Need(NewGameWork.Enabled(w)&&Enum.IsDefined(i.Action)&&Enum.IsDefined(i.Rate)&&EntityId.IsValid(i.Id.Value)&&MaterialMarkets.Sites(w).Contains(i.Site)&&Authority(w,actor,i.Owner,i.Site,at,rev),"現地の管轄と行政の権限を確認してください");var principal=HouseSuccession.Head(w,i.Owner,at,rev);long due=at,rice=0,coins=0;int crew=0;SurveyBook? result=null;
 if(i.Action is SurveyAction.Statement or SurveyAction.Measurement){Need(i.Reference==null&&!Entries(w).Any(e=>Job(e)&&e.Input.Site==i.Site&&Before(e,at,rev)&&at<e.Due),"既に現地の調査が進んでいます");bool measured=i.Action==SurveyAction.Measurement;crew=measured?10:5;rice=measured?100:20;coins=measured?30:10;due=checked(at+(measured?7:2)*86400L);var a=CommunityEconomy.AccountAt(w,i.Site,at,rev);Need(a.Hunger==0&&a.Workforce-a.Reserved>=crew&&a.HouseRice-HouseSalary.Reserved(w,i.Site,at,rev)>=rice&&RegionalDomains.Cash(w,i.Site,at,rev)>=coins&&RegionalDomains.Remaining(w,actor,i.Site,at,rev)>=coins&&VillageConsultation.Cooperative(w,i.Site,at,rev),"現地の人手・食事・経費と村の協力を確認してください");}
 else if(i.Action==SurveyAction.ReadBook){Need(i.Reference!=null,"読む帳面を選んでください");var source=Source(w,i.Reference.Value);Need(Job(source)&&source.Input.Owner==i.Owner&&source.Input.Site==i.Site&&!Entries(w).Any(e=>e.Input.Action==SurveyAction.ReadBook&&e.Input.Reference==source.Input.Id&&e.Actor==actor&&Before(e,at,rev)),"自家の現地の帳面か、既に読んだものです");result=w.Surveys!.Books.Single(b=>b.Job==source.Input.Id&&b.At<=at&&b.Revision<=rev);}
 else {Need(principal==actor,"年貢の方針は管轄する当主が決めます");if(i.Reference!=null){result=KnownBooks(w,actor,at,rev).Single(b=>b.Job==i.Reference);var source=Source(w,result.Job);Need(source.Input.Owner==i.Owner&&source.Input.Site==i.Site,"別の地域の帳面では課税できません");}due=checked(at+7*86400L);}
 return new(i,actor,principal,at,rev,due,rice,coins,crew,result);}
 static string PaperId(EntityId reading)=>"message:survey/"+ContractJson.Hash(Encoding.UTF8.GetBytes(reading.Value))[..28];
 static MessageEnvelope Envelope(SurveyPaper p)=>new(p.Id,p.Reading.Value,MessageKind,p.Sender.Value,p.Recipient.Value,Encoding.UTF8.GetString(ContractJson.Write(p)),p.Site.Value,p.At);
 public static void Execute(ContractWorld w,SurveyInput i,EntityId actor){var e=Make(w,i,actor,w.ElapsedSeconds,w.CommitSequence);w.Surveys??=new(1,Policy,[],[],[]);w.Surveys=w.Surveys with{Entries=[..Entries(w),e]};if(i.Action==SurveyAction.ReadBook&&e.Principal!=actor){var address=new EntityId(w.NewGame!.Start.People.Single(p=>p.Id==e.Principal.Value).Site);var paper=new SurveyPaper(PaperId(i.Id),i.Id,actor,e.Principal,address,i.Site,e.At,e.Revision,e.Result!);w.Surveys=w.Surveys with{Papers=[..w.Surveys.Papers,paper]};MessageFlow.Send(w.Messaging,Envelope(paper),e.At,1);w.SealedMessages=[..w.SealedMessages,new(paper.Id)];}}
 internal static void Tick(ContractWorld w,bool advanced){if(w.Surveys==null)return;foreach(var job in Entries(w).Where(e=>Job(e)&&e.Due<=w.ElapsedSeconds&&!w.Surveys.Books.Any(b=>b.Job==e.Input.Id)).ToArray())w.Surveys=w.Surveys with{Books=[..w.Surveys.Books,Complete(w,job,w.CommitSequence)]};if(!advanced||Entries(w).Any(e=>e.Revision==w.CommitSequence))return;var acting=LiveTerritory.Acting(w);
 foreach(var paper in w.Surveys.Papers.Where(p=>p.Recipient!=w.PlayerControl&&w.Messaging.Attempts.Any(a=>a.MessageId==p.Id&&a.ReceiverId==p.Recipient.Value&&a.Status==AttemptStatus.Delivered)))if(!MessageFlow.Knows(w.Messaging,paper.Id,paper.Recipient.Value))w.Messaging.Knowledge=[..w.Messaging.Knowledge,new(paper.Id,paper.Recipient.Value,w.ElapsedSeconds,paper.Id)];
 foreach(var job in Entries(w).Where(e=>Job(e)&&e.Actor!=w.PlayerControl&&acting(e.Actor)&&e.Due<=w.ElapsedSeconds&&!Entries(w).Any(a=>a.Input.Action==SurveyAction.ReadBook&&a.Input.Reference==e.Input.Id&&a.Actor==e.Actor)).ToArray())if(TransactionalWorld.TryApply(w,c=>Execute(c,new(Id("read/"+job.Input.Id.Value),SurveyAction.ReadBook,job.Input.Owner,job.Input.Site,job.Input.Id),job.Actor)))return;
 foreach(var f in HouseSuccession.Factions(w)){var head=new EntityId(f.Head);var owner=new EntityId(f.Id);if(head==w.PlayerControl||!acting(head)||SocialWorld.Site(w,head) is not {} site||!MaterialMarkets.Sites(w).Contains(site)||RegionalDomains.Owner(w,site)!=owner)continue;var known=KnownBooks(w,head).Where(b=>Source(w,b.Job).Input.Site==site).OrderBy(b=>b.At).LastOrDefault();if(known!=null&&!Entries(w).Any(e=>e.Input.Action==SurveyAction.PostRate&&e.Actor==head&&e.Input.Reference==known.Job)){var a=CommunityEconomy.AccountAt(w,site,w.ElapsedSeconds,w.CommitSequence+1);var rate=a.Hunger>0?LandTaxRate.Gentle:LandTaxRate.Ordinary;if(TransactionalWorld.TryApply(w,c=>Execute(c,new(Id("decree/"+known.Job.Value),SurveyAction.PostRate,owner,site,known.Job,rate),head)))return;}
 int year=DateOnly.Parse(w.EpochDate).AddDays((int)(w.ElapsedSeconds/86400)).Year;if(!Entries(w).Any(e=>Job(e)&&e.Input.Site==site&&DateOnly.Parse(w.EpochDate).AddDays((int)(e.At/86400)).Year==year))if(TransactionalWorld.TryApply(w,c=>Execute(c,new(Id("npc-survey/"+site.Value+"/"+year),SurveyAction.Measurement,owner,site),head)))return;}}
 internal static long? NextBoundary(ContractWorld w,long target)=>Entries(w).Select(e=>e.Due).Where(t=>t>w.ElapsedSeconds&&t<=target).Order().Select(t=>(long?)t).FirstOrDefault();
 public static void Validate(ContractWorld w,ContractWorld? prior){if(w.Surveys==null){Need(prior?.Surveys==null,"調査と布告の原本が消えています");return;}Need(NewGameWork.Enabled(w)&&w.Surveys.Schema==1&&w.Surveys.Policy==Policy&&(Entries(w).Length>0||LiveTerritory.Enabled(w)),"調査の保存形式が不正です");if(prior?.Surveys!=null){Need(ContractJson.CanonicalHash(Entries(w).Take(prior.Surveys.Entries.Length).ToArray())==ContractJson.CanonicalHash(prior.Surveys.Entries),"過去の調査が改変されています");Need(w.Surveys.Books.Take(prior.Surveys.Books.Length).SequenceEqual(prior.Surveys.Books)&&w.Surveys.Papers.Take(prior.Surveys.Papers.Length).SequenceEqual(prior.Surveys.Papers),"過去の帳面・報告を変えています");}long rev=0,at=0;var ids=new HashSet<EntityId>();var prefix=new List<SurveyEntry>();foreach(var e in Entries(w)){Need(e.Revision>rev&&e.Revision<=w.CommitSequence&&e.At>=at&&e.At<=w.ElapsedSeconds&&ids.Add(e.Input.Id),"調査の順序が不正です");var history=w.ForkTransportLocation();history.Surveys=w.Surveys with{Entries=prefix.ToArray()};Need(e==Make(history,e.Input,e.Actor,e.At,e.Revision),"当時の権限・労働・経費・既知の帳面と違います");prefix.Add(e);rev=e.Revision;at=e.At;}
 Need(w.Surveys.Books.Select(b=>b.Job).Distinct().Count()==w.Surveys.Books.Length,"二重の検地簿です");foreach(var b in w.Surveys.Books){var source=Source(w,b.Job);Need(Job(source)&&b.At==source.Due&&b.At<=w.ElapsedSeconds&&b.Revision>source.Revision&&b.Revision<=w.CommitSequence&&b==Complete(w,source,b.Revision),"工期・実測と帳面が一致しません");}
 foreach(var p in w.Surveys.Papers){var e=Source(w,p.Reading);Need(e.Input.Action==SurveyAction.ReadBook&&p.Id==PaperId(e.Input.Id)&&p.Sender==e.Actor&&p.Recipient==e.Principal&&p.Recipient!=p.Sender&&p.Site==e.Input.Site&&p.At==e.At&&p.Revision==e.Revision&&p.Book==e.Result&&w.Messaging.Messages.Count(m=>m==Envelope(p))==1&&w.SealedMessages.Contains(new(p.Id)),"現地の帳面と物理報告が違います");}Need(w.Messaging.Messages.Count(m=>m.Kind==MessageKind)==w.Surveys.Papers.Length,"調査報告の孤立原本です");}
}
public sealed partial class WorldSession
{
 public CommandResult ManageLandSurvey(SurveyInput i,long revision){using var _ccRev=ControlContext.At(revision);lock(gate){var old=LandSurvey.Entries(state).SingleOrDefault(e=>e.Input.Id==i.Id);if(old!=null)return new(old.Input==i?ResultCode.AlreadyAccepted:ResultCode.IdPayloadConflict,i.Id,state.CommitSequence,"この原本は受付済みです");if(revision!=state.CommitSequence)return new(ResultCode.StateChanged,i.Id,state.CommitSequence,"表示を更新してください");if(NewGameWork.OwnIdUsed(state,i.Id)||state.Requests.Any(q=>q.Id==i.Id))return new(ResultCode.IdPayloadConflict,i.Id,state.CommitSequence,"別の操作で使用したIDです");try{Change(w=>LandSurvey.Execute(w,i,w.PlayerControl));return new(ResultCode.Accepted,i.Id,state.CommitSequence,"申告・実測・本人の認識と布告の効力を分けて記録しました");}catch(Exception e)when(e is InvalidDataException or InvalidOperationException or ArgumentException or OverflowException){return new(ResultCode.NotAvailable,i.Id,state.CommitSequence,e.Message);}}}
}
